    internal InnerPlaybackConfigurationHttpRequestFactory HttpRequestFactory { get; set; }

    internal InnerPlaybackConfigurationVastResponseFactory VastResponseFactory { get; set; }

    protected override Humidifier.MediaTailor.PlaybackConfigurationTypes.AdDecisionServerConfiguration Create()
    {
        var adDecisionServerConfigurationResult = CreateAdDecisionServerConfiguration();
        factoryAction?.Invoke(adDecisionServerConfigurationResult);

        return adDecisionServerConfigurationResult;
    }

    private Humidifier.MediaTailor.PlaybackConfigurationTypes.AdDecisionServerConfiguration CreateAdDecisionServerConfiguration()
    {
        var adDecisionServerConfigurationResult = new Humidifier.MediaTailor.PlaybackConfigurationTypes.AdDecisionServerConfiguration();

        return adDecisionServerConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PlaybackConfigurationTypes.AdDecisionServerConfiguration result)
    {
        base.CreateChildren(result);

        result.HttpRequest ??= HttpRequestFactory?.Build();
        result.VastResponse ??= VastResponseFactory?.Build();
    }

} // End Of Class

